INSERT INTO "deferred_defect" (id,found_during,defect,evidence,at) VALUES (1,'AVRIG-00001','`cargo check --workspace` fails on `avrig-desktop`. RC.EXE rejects `apps/desktop/src-tauri/icons/icon.ico` as an old DIB because the file is a 22-byte placeholder committed in `f7b70fa`. Pre-existing: the same 22-byte file is present at the `0.4.0` release tag, so `0.4.0` shipped with it. The release path is unaffected, since `make build` runs `cargo build --release` and never references `src-tauri`. `cargo check --workspace --exclude avrig-desktop` exits 0.','AVRIG-00001, Pass 11','2026-11-20T02:58:11.871Z');
INSERT INTO "deferred_defect" (id,found_during,defect,evidence,at) VALUES (2,'AVRIG-00001','`scripts/bump-version.ps1` runs `cargo check --workspace` at line 85 and prints `Successfully bumped version to $newVersion` at line 90 with no `$LASTEXITCODE` check between them, so it reports success over a failed lock sync.','AVRIG-00001, Pass 11','2026-11-20T02:58:11.871Z');
INSERT INTO "deferred_defect" (id,found_during,defect,evidence,at) VALUES (3,'AVRIG-00001','`scripts/check-version-sync.ps1` compares only `avrig-ai`''s `Cargo.toml` against `apps/web/package.json`, never against `avrig-api`, so the release set can hold a `0.5.0` tag on a `0.4.0` binary.','AVRIG-00001, Pass 13','2026-11-20T02:58:11.871Z');
INSERT INTO "deferred_defect" (id,found_during,defect,evidence,at) VALUES (4,'AVRIG-00001','The Agentic `.gitignore` rule `*.bak-*` requires a timestamp, so a bare `<file>.bak` backup is not ignored. `AGENTS.md.bak` (31 lines, modified 2026-11-12) sits untracked in the Agentic checkout. Not a regression, since it predates this plan and was inside the measured D14 baseline, but a `git add -A` would sweep it.','AVRIG-00001, stage 16','2026-11-20T02:58:11.871Z');
INSERT INTO "deferred_defect" (id,found_during,defect,evidence,at) VALUES (5,'AVRIG-00001','The `bump-version` Makefile target guards with a POSIX test, `if [ -z "$(VERSION)" ]`, but `SHELL := sh.exe` is not on `PATH` by default here, so GNU Make falls back to `cmd.exe` and the guard fails with `-z was unexpected at this time`.','AVRIG-00001, Pass 11','2026-11-20T02:58:11.871Z');
INSERT INTO "deferred_defect" (id,found_during,defect,evidence,at) VALUES (6,'AVRIG-00003','`D:\Cloud\OneDrive\AI\Agentic\.opencode\agents\` is untracked in the Agentic repository: `git ls-files .opencode/agents` returns nothing and the directory shows as `??`. Every subagent definition, including the one this plan edits, therefore has no version history, so a definition change cannot be covered by a branch commit or a candidate tag and cannot be diffed after the fact. `AVRIG-00003` works around it with a hash manifest, which pins content but does not restore reviewability. Versioning the directory is a governance decision and needs its own plan.','AVRIG-00003, stage 4','2026-11-20T02:58:11.871Z');

CREATE INDEX ix_work_item_state ON work_item (state);

CREATE TRIGGER tr_allocation_event_no_delete
BEFORE DELETE ON allocation_event
BEGIN SELECT RAISE(ABORT, 'allocation_event is append-only'); END;

CREATE TRIGGER tr_allocation_event_no_update
BEFORE UPDATE ON allocation_event
BEGIN SELECT RAISE(ABORT, 'allocation_event is append-only'); END;

CREATE TRIGGER tr_work_item_no_delete
BEFORE DELETE ON work_item
BEGIN SELECT RAISE(ABORT, 'work_item rows are permanent; void the row instead of deleting it'); END;

CREATE TRIGGER tr_work_item_no_rekey
BEFORE UPDATE OF indicator, number ON work_item
BEGIN SELECT RAISE(ABORT, 'indicator and number are immutable once written'); END;

COMMIT;
